[asy]
unitsize(0.5 cm);

pair A = (sqrt(2),-5*sqrt(2)), B = (4,6);

draw((-2,0)--(5,0));
draw((0,-8)--(0,8));
draw((0,0)--A,dashed);
draw((0,0)--B,dashed);

dot("$\sqrt{2} - 5 \sqrt{2} i$", A, S);
dot("$4 + 6i$", B,  NE);
[/asy]

